output_text:
[
  {
    "id": "cartless_entry_bypass",
    "text": "A shopper should first pass the entrance cart station without taking the cart, as a cartless entry check.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": "at(1,5)",
        "cartless": {
          "not": "hasCart"
        },
        "entrance_cart_available": {
          "and": [
            "entry_cart_station",
            "cartAt(1,5)",
            "cartless"
          ]
        }
      },
      "events": {
        "bypass_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_available",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              {
                "not": "at(1,5)"
              },
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "bypass_entrance_cart"
    }
  },
  {
    "id": "cartless_front_left_survey",
    "text": "Before normal shopping, a shopper should make a short cartless survey of the front-left aisle area.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        },
        "front_left_survey_zone": {
          "or": [
            "at(0,3)",
            "at(1,3)",
            "at(1,4)",
            "at(2,5)"
          ]
        }
      },
      "events": {
        "cartless_survey_step": {
          "pre": {
            "and": [
              "cartless",
              "front_left_survey_zone",
              "MOVE"
            ]
          },
          "post": "cartless"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cartless_survey_step"
    }
  },
  {
    "id": "take_entrance_cart",
    "text": "A shopper should take the entrance cart from the cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": "at(1,5)",
        "entry_cart_available": {
          "and": [
            "entry_cart_station",
            "cartAt(1,5)"
          ]
        },
        "has_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_cartless_item_pickup",
    "text": "Items should be picked up only while the shopper has a cart, never into the shopper's hands.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cartless": {
          "not": "has_cart"
        },
        "carrying_by_hand": "handFull"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "pickup_item_without_cart",
          "carrying_by_hand"
        ]
      }
    }
  },
  {
    "id": "reclaim_temporary_cart_drop",
    "text": "If a cart is put down anywhere other than the return bay, the shopper must pick it back up before leaving.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cartless": {
          "not": "has_cart"
        },
        "return_bay": "at(0,1)",
        "not_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {
        "temporary_cart_drop": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "has_cart",
              "not_return_bay"
            ]
          },
          "post": "cartless"
        },
        "recover_cart": {
          "pre": "PICKUP_CART",
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "temporary_cart_drop",
      "discharge": "recover_cart"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "The shopper should return the cart by leaving it at the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "at_return_bay_with_cart": {
          "and": [
            "return_bay",
            "has_cart"
          ]
        }
      },
      "events": {
        "return_cart": {
          "pre": {
            "and": [
              "at_return_bay_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart"
    }
  },
  {
    "id": "checkout_side_cartless_only",
    "text": "Carts are not allowed on the checkout side of the store, although the shopper may enter that area after parking the cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "checkout_side": {
          "or": [
            "at(6,2)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_checkout_side": {
          "and": [
            "has_cart",
            "checkout_side"
          ]
        }
      },
      "events": {
        "move_cart_into_checkout_side": {
          "pre": {
            "and": [
              "MOVE",
              "has_cart"
            ]
          },
          "post": "cart_in_checkout_side"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_in_checkout_side",
          "move_cart_into_checkout_side"
        ]
      }
    }
  },
  {
    "id": "return_bay_carted_overshoot",
    "text": "As a return-bay check, the shopper should roll the cart out of the return bay once before finally leaving it there.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "return_bay": "at(0,1)",
        "at_return_bay_with_cart": {
          "and": [
            "return_bay",
            "has_cart"
          ]
        }
      },
      "events": {
        "carted_bay_overshoot": {
          "pre": {
            "and": [
              "at_return_bay_with_cart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "has_cart",
              {
                "not": "return_bay"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "carted_bay_overshoot"
    }
  }
]
